// We use the Verus verifier to prove that the produced sequence
// has length `n`, uses only 'a' and 'b', and satisfies the
// constraint that for all 0 ≤ i ≤ n-3, s[i] ≠ s[i+2].

#![allow(unused)]
verus! {

    /// Construct a length-n string over {'a','b'} satisfying:
    ///   1) For all 0 ≤ i ≤ n-3, s[i] ≠ s[i+2].
    ///   2) Never uses 'c'.
    ///
    /// We prove by construction using the repeating pattern "aabb".
    fn solve(n: i8) -> Vec<char>
        requires n >= 1
        ensures |res: &Vec<char>|
            // exact length
            res.len() == (n as usize)
            // no 'c' anywhere
            && forall |i: int|
                  0 <= i && i < (res.len() as int)
                  ==> res[i as usize] != 'c'
            // constraint s[i] ≠ s[i+2] for all applicable i
            && forall |i: int|
                  0 <= i && i + 2 < (res.len() as int)
                  ==> res[i as usize] != res[(i + 2) as usize]
    {
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // We build res[0..n) one character at a time.
        // At each step we maintain
        //   1) res.len() == i,
        //   2) no element in res equals 'c',
        //   3) for all j with j+2 < i, res[j] ≠ res[j+2].
        // We decrease `(n as usize) - i` to prove termination.
        while i < (n as usize)
            invariant i <= (n as usize)
            invariant res.len() == i
            invariant forall |j: int|
                      0 <= j && j + 2 < (i as int)
                      ==> res[j as usize] != res[(j + 2) as usize]
            invariant forall |j: int|
                      0 <= j && j < (i as int)
                      ==> res[j as usize] != 'c'
            decreases (n as usize) - i
        {
            // Use the repeating pattern "aabb":
            // indices 0,1 → 'a'; indices 2,3 → 'b'; then repeat.
            let ch = if i % 4 < 2 { 'a' } else { 'b' };
            res.push(ch);
            i += 1;
        }

        res
    }

    // Simple smoke test (not required by Verus, but for illustration):
    #[verifier(test)]
    fn test_solve() {
        let v = solve(10);
        assert(v.len() == 10);
        // Check no 'c'
        assert(forall(|i: int| 0 <= i && i < 10 ==> v[i as usize] != 'c'));
        // Check the distance-2 constraint
        assert(forall(|i: int| 0 <= i && i + 2 < 10 ==> v[i as usize] != v[(i+2) as usize]));
    }
}